//! The Rust report builder must render exactly what Sparrow's
//! `V3LeanReportBuilder.java` renders, and every report must validate against
//! `docs/blueberry-v1/privacy-report.schema.json`.
//!
//! `java_parity.json` was generated by running the Java builder over 500 tags
//! (200 structured + 300 random): `[tag, grade, score, urgency, headline,
//! [[id, title, severity, confidence], …]]`.

use perseverus_sdk::report::{self, InputRef, PrivacyReport, Severity};

fn input() -> InputRef {
    InputRef {
        txid: "14cdd7d7ae837f5523e3495c6bef2f0e06e87ca658c6e1a4d831ac6253a13621".into(),
        vout: 1,
        block_height: 927_316,
        value_sats: Some(12_345),
    }
}

fn sev(s: &str) -> Severity {
    match s {
        "critical" => Severity::Critical,
        "high" => Severity::High,
        "medium" => Severity::Medium,
        "low" => Severity::Low,
        "good" => Severity::Good,
        _ => Severity::Info,
    }
}

#[test]
fn matches_java_builder() {
    let fixture: Vec<serde_json::Value> =
        serde_json::from_str(include_str!("java_parity.json")).unwrap();
    assert_eq!(fixture.len(), 500);
    for row in fixture {
        let tag = row[0].as_u64().unwrap() as u32;
        let r = report::graded(input(), tag, true);
        assert_eq!(r.grade.as_deref(), row[1].as_str(), "grade, tag {tag:06x}");
        assert_eq!(r.score, Some(row[2].as_u64().unwrap() as u32), "score, tag {tag:06x}");
        let rec = r.primary_recommendation.as_ref().unwrap();
        assert_eq!(rec.urgency, row[3].as_str().unwrap(), "urgency, tag {tag:06x}");
        assert_eq!(rec.headline, row[4].as_str().unwrap(), "headline, tag {tag:06x}");
        let want = row[5].as_array().unwrap();
        assert_eq!(r.findings.len(), want.len(), "finding count, tag {tag:06x}");
        for (f, w) in r.findings.iter().zip(want) {
            assert_eq!(f.id, w[0].as_str().unwrap(), "tag {tag:06x}");
            assert_eq!(f.title, w[1].as_str().unwrap(), "tag {tag:06x}");
            assert_eq!(f.severity, sev(w[2].as_str().unwrap()), "tag {tag:06x}");
            assert_eq!(f.confidence, w[3].as_str().unwrap(), "tag {tag:06x}");
        }
    }
}

fn validate(r: &PrivacyReport) {
    let schema: serde_json::Value = serde_json::from_str(include_str!(
        "../../docs/blueberry-v1/privacy-report.schema.json"
    ))
    .unwrap();
    let validator = jsonschema::validator_for(&schema).expect("schema compiles");
    let inst: serde_json::Value = serde_json::from_str(&r.to_json()).unwrap();
    let errors: Vec<String> = validator.iter_errors(&inst).map(|e| format!("{} at {}", e, e.instance_path)).collect();
    assert!(errors.is_empty(), "{:?} invalid: {errors:#?}\n{}", r.status, r.to_json());
}

#[test]
fn every_report_kind_matches_schema() {
    for tag in [0u32, 0x00_00_86, 0xe000d6, 0xFF_FF_FF, 0x01_23_45] {
        validate(&report::graded(input(), tag, true));
    }
    validate(&report::ungraded(input()));
    validate(&report::not_covered(input()));
    validate(&report::failed(input(), "spend_rejected", "403: proof verification failed".into(), false));
}

#[test]
fn ungraded_never_counts_toward_average() {
    let r = report::ungraded(input());
    assert!(!r.include_in_wallet_average && !r.token_spent);
    assert_eq!(r.findings.len(), 6);
    assert!(r.findings.iter().all(|f| f.severity == Severity::Info));
}
